import pickle
import sys

from flake8._compat import importlib_metadata


def test_entrypoint_picklable():
    ep = importlib_metadata.EntryPoint(
        name="test", value="test_module", group="flake8.extension"
    )
    if sys.version_info[:3] == (3, 8, 0):
        # On Python 3.8.0, unpickling may fail due to recursion
        try:
            pickle.loads(pickle.dumps(ep))
        except RecursionError:
            raise AssertionError(
                "EntryPoint is not picklable on Python 3.8.0"
            )
    else:
        pickle.loads(pickle.dumps(ep))

