from bs4 import BeautifulSoup


def test_version_headings_have_stable_anchors() -> None:
    with open("CHANGES.md", encoding="utf-8") as f:
        changes = f.read()
    html = commonmark.commonmark(changes)
    soup = BeautifulSoup(html, "html.parser")
    h2s = soup.find_all("h2")
    # Check that a known older release gets a deterministic, version-based id.
    for h2 in h2s:
        text = h2.get_text(strip=True)
        if text == "19.10b0":
            assert h2.get("id") is not None and h2["id"].startswith("version-")
            break
    else:
        # If we never saw the old-style heading, the test is moot; skip by passing
        pass

    # Also ensure "Unreleased" heading hasn't been touched
    for h2 in h2s:
        if h2.get_text(strip=True) == "Unreleased":
            assert h2.get("id") is not None
            break
    else:
        # If there is no Unreleased heading, that's fine too
        pass
"
